    g.fillStyle = base; g.fillRect(0, 0, 128, 128);
    for (var y = 0; y < 128; y += 12) { g.fillStyle = 'rgba(0,0,0,.28)'; g.fillRect(0, y + 9, 128, 3); for (var x = (y / 12 % 2) * 8; x < 128; x += 16) { g.fillStyle = 'rgba(255,255,255,.08)'; g.fillRect(x, y, 8, 9); g.fillStyle = 'rgba(0,0,0,.15)'; g.fillRect(x + 7, y, 1, 9); } }
    if (edge) { g.fillStyle = edge; g.fillRect(0, 0, 128, 10); }
