        var tb = new T.Mesh(new T.TubeGeometry(c, 20, .09, 6, false), mats.gold); tb.position.z = sd * L / 2; grp.add(tb);
        var head = new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3([new T.Vector3(lr * (-w / 2 - e), -h * .03, 0), new T.Vector3(lr * (-w / 2 - e * 1.5), h * .05, 0), new T.Vector3(lr * (-w / 2 - e * 1.6), h * .22, 0)]), 8, .11, 6, false), mats.gold);
        head.position.z = sd * L / 2; grp.add(head);
