    var tileG = new T.MeshStandardMaterial({ map: tileTex('#2f6a3a', '#c8641c'), emissive: 0x0e2a14, emissiveIntensity: .6, roughness: .55 });
    var wall = new T.MeshStandardMaterial({ color: 0xe8d8b0, emissive: 0x4a3a20, emissiveIntensity: o.glow ? o.glow * .3 : .32, roughness: .8 });
    var stone = new T.MeshStandardMaterial({ color: 0x9a907a, emissive: 0x2a2418, emissiveIntensity: .5, roughness: .9 });
    var mats = { tile: tileO, gold: gold };
